Add-Type -AssemblyName PresentationFramework
Add-Type -AssemblyName PresentationCore
Add-Type -AssemblyName WindowsBase

[xml]$xaml = @'
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
 Title="Media Forge" Width="1080" Height="710" MinWidth="900" MinHeight="620" WindowStartupLocation="CenterScreen"
 Background="#F5F5F3" FontFamily="Segoe UI Variable Text,Segoe UI" AllowDrop="True">
 <Window.Resources>
  <Style TargetType="Button">
   <Setter Property="Background" Value="#111111"/><Setter Property="Foreground" Value="White"/><Setter Property="BorderThickness" Value="0"/><Setter Property="Padding" Value="16,10"/><Setter Property="Cursor" Value="Hand"/>
   <Setter Property="Template"><Setter.Value><ControlTemplate TargetType="Button"><Border x:Name="bg" Background="{TemplateBinding Background}" CornerRadius="10" Padding="{TemplateBinding Padding}"><ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/></Border><ControlTemplate.Triggers><Trigger Property="IsMouseOver" Value="True"><Setter TargetName="bg" Property="Opacity" Value="0.82"/></Trigger><Trigger Property="IsEnabled" Value="False"><Setter TargetName="bg" Property="Opacity" Value="0.35"/></Trigger></ControlTemplate.Triggers></ControlTemplate></Setter.Value></Setter>
  </Style>
  <Style TargetType="ComboBoxItem"><Setter Property="Foreground" Value="#111111"/><Setter Property="Background" Value="White"/><Setter Property="Padding" Value="12,9"/><Setter Property="Template"><Setter.Value><ControlTemplate TargetType="ComboBoxItem"><Border x:Name="b" Background="{TemplateBinding Background}" CornerRadius="7" Padding="{TemplateBinding Padding}"><ContentPresenter/></Border><ControlTemplate.Triggers><Trigger Property="IsHighlighted" Value="True"><Setter TargetName="b" Property="Background" Value="#EEEEEB"/></Trigger><Trigger Property="IsSelected" Value="True"><Setter TargetName="b" Property="Background" Value="#DFDFDB"/></Trigger></ControlTemplate.Triggers></ControlTemplate></Setter.Value></Setter>
  </Style>
  <Style TargetType="ComboBox"><Setter Property="Foreground" Value="#111111"/><Setter Property="Background" Value="White"/><Setter Property="BorderBrush" Value="#D8D8D3"/><Setter Property="Height" Value="44"/><Setter Property="Template"><Setter.Value><ControlTemplate TargetType="ComboBox"><Grid><ToggleButton Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="1" Focusable="False" IsChecked="{Binding IsDropDownOpen,RelativeSource={RelativeSource TemplatedParent},Mode=TwoWay}"><ToggleButton.Template><ControlTemplate TargetType="ToggleButton"><Border Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="1" CornerRadius="10"><Grid><ContentPresenter Margin="13,0,35,0" VerticalAlignment="Center" Content="{Binding SelectionBoxItem,RelativeSource={RelativeSource AncestorType=ComboBox}}"/><Path Data="M0,0 L4,4 L8,0" Stroke="#555555" StrokeThickness="1.5" HorizontalAlignment="Right" VerticalAlignment="Center" Margin="0,0,14,0"/></Grid></Border></ControlTemplate></ToggleButton.Template></ToggleButton><Popup Placement="Bottom" IsOpen="{TemplateBinding IsDropDownOpen}" AllowsTransparency="True" PopupAnimation="Fade"><Border Background="White" BorderBrush="#D8D8D3" BorderThickness="1" CornerRadius="10" Padding="4" Margin="0,4,0,0" MinWidth="{Binding ActualWidth,RelativeSource={RelativeSource TemplatedParent}}"><ScrollViewer><ItemsPresenter/></ScrollViewer></Border></Popup></Grid></ControlTemplate></Setter.Value></Setter>
  </Style>
  <Style TargetType="TextBox"><Setter Property="Background" Value="#F7F7F5"/><Setter Property="Foreground" Value="#111111"/><Setter Property="BorderBrush" Value="#D8D8D3"/><Setter Property="BorderThickness" Value="1"/><Setter Property="Padding" Value="12,10"/><Setter Property="FontSize" Value="14"/></Style>
 </Window.Resources>
 <Grid Margin="34,28,34,28">
  <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="28"/><RowDefinition Height="*"/><RowDefinition Height="22"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
  <Grid>
   <StackPanel><TextBlock Text="Media Forge" FontSize="25" FontWeight="SemiBold" Foreground="#111111"/><TextBlock Text="Конвертация и сжатие без лишнего" FontSize="13" Foreground="#767670" Margin="0,4,0,0"/></StackPanel>
   <Button x:Name="AddButton" Width="46" Height="46" Padding="0" HorizontalAlignment="Right" ToolTip="Добавить файлы"><Path Data="M8,1 L8,15 M1,8 L15,8" Stroke="White" StrokeThickness="2" Width="16" Height="16" Stretch="Uniform"/></Button>
  </Grid>
  <Grid Grid.Row="2"><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition x:Name="SettingsColumn" Width="0"/></Grid.ColumnDefinitions>
   <Border Background="White" CornerRadius="16" Margin="0,0,18,0" Padding="18">
    <Grid><Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="14"/><RowDefinition Height="*"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
     <Grid><TextBlock x:Name="QueueTitle" Text="Файлы · 0" FontSize="16" FontWeight="SemiBold" Foreground="#111111"/><Button x:Name="ClearButton" Content="Очистить" HorizontalAlignment="Right" Background="Transparent" Foreground="#777771" Padding="8,4"/></Grid>
     <Grid Grid.Row="2">
      <TreeView x:Name="FileList" BorderThickness="0" Background="Transparent" ScrollViewer.HorizontalScrollBarVisibility="Disabled">
       <TreeView.ItemContainerStyle><Style TargetType="TreeViewItem"><Setter Property="IsExpanded" Value="True"/><Setter Property="HorizontalContentAlignment" Value="Stretch"/><Setter Property="Margin" Value="0,0,0,6"/><Setter Property="Padding" Value="2"/><Setter Property="Background" Value="Transparent"/><Setter Property="Foreground" Value="#111111"/><Style.Triggers><Trigger Property="IsSelected" Value="True"><Setter Property="Background" Value="#E7E7E3"/><Setter Property="BorderBrush" Value="#BEBEB8"/><Setter Property="BorderThickness" Value="1"/></Trigger></Style.Triggers></Style></TreeView.ItemContainerStyle>
       <TreeView.ItemTemplate><HierarchicalDataTemplate ItemsSource="{Binding Children}"><Border Background="#F7F7F5" CornerRadius="10" Padding="10" MinHeight="54"><Grid><Grid.ColumnDefinitions><ColumnDefinition Width="48"/><ColumnDefinition Width="*"/><ColumnDefinition Width="90"/></Grid.ColumnDefinitions><Border x:Name="ThumbBg" Width="40" Height="40" CornerRadius="8" Background="#E2E2DE" ClipToBounds="True"><Grid><Image x:Name="Thumb" Source="{Binding Thumbnail}" Stretch="UniformToFill"/><Path x:Name="FileIcon" Data="M3,1 L11,1 L15,5 L15,17 L3,17 Z M11,1 L11,5 L15,5" Stroke="#333333" StrokeThickness="1.3" Width="15" Height="17" Stretch="Uniform"/></Grid></Border><StackPanel Grid.Column="1" VerticalAlignment="Center"><TextBlock Text="{Binding Name}" FontWeight="SemiBold" TextTrimming="CharacterEllipsis"/><TextBlock Text="{Binding Category}" FontSize="11" Foreground="#777771" Margin="0,2,0,0"/></StackPanel><TextBlock Grid.Column="2" Text="{Binding Size}" HorizontalAlignment="Right" VerticalAlignment="Center" Foreground="#777771"/></Grid></Border><HierarchicalDataTemplate.Triggers><DataTrigger Binding="{Binding IsImage}" Value="True"><Setter TargetName="FileIcon" Property="Visibility" Value="Collapsed"/></DataTrigger><DataTrigger Binding="{Binding IsFolder}" Value="True"><Setter TargetName="Thumb" Property="Visibility" Value="Collapsed"/><Setter TargetName="FileIcon" Property="Data" Value="M2,4 L7,4 L9,6 L18,6 L18,16 L2,16 Z"/><Setter TargetName="ThumbBg" Property="Background" Value="#ECECE8"/></DataTrigger></HierarchicalDataTemplate.Triggers></HierarchicalDataTemplate></TreeView.ItemTemplate>
      </TreeView>
      <StackPanel x:Name="EmptyState" VerticalAlignment="Center" HorizontalAlignment="Center"><Path Data="M2,3 L7,3 L9,5 L18,5 L18,15 L2,15 Z" Stroke="#A0A09A" StrokeThickness="1.4" Width="42" Height="34" Stretch="Uniform"/><TextBlock Text="Файлов пока нет" Foreground="#6E6E68" FontSize="14" Margin="0,13,0,0" HorizontalAlignment="Center"/><TextBlock Text="Нажмите +, чтобы добавить" Foreground="#A0A09A" FontSize="12" Margin="0,4,0,0"/></StackPanel>
     </Grid>
     <StackPanel Grid.Row="3" Orientation="Horizontal" Margin="0,10,0,0"><Button x:Name="FolderButton" Content="＋ Папка" Background="#EEEEEB" Foreground="#111111" Padding="12,8"/><Button x:Name="RenameButton" Content="Переименовать" Background="#EEEEEB" Foreground="#111111" Padding="12,8" Margin="6,0,0,0"/><Button x:Name="RemoveButton" Content="Удалить" Background="Transparent" Foreground="#777771" Padding="12,8" Margin="6,0,0,0"/></StackPanel>
    </Grid>
   </Border>
   <Border x:Name="SettingsPanel" Grid.Column="1" Background="White" CornerRadius="16" Padding="20" Visibility="Collapsed">
    <StackPanel><TextBlock Text="Что сделать" FontSize="16" FontWeight="SemiBold" Foreground="#111111"/><TextBlock Text="Программа покажет только доступные действия" TextWrapping="Wrap" Foreground="#85857F" FontSize="12" Margin="0,5,0,18"/><TextBlock Text="ДЕЙСТВИЕ" Foreground="#777771" FontSize="10" FontWeight="Bold"/><ComboBox x:Name="ActionBox" Margin="0,6,0,16"/><TextBlock Text="ФОРМАТ" Foreground="#777771" FontSize="10" FontWeight="Bold"/><ComboBox x:Name="FormatBox" Margin="0,6,0,16"/><TextBlock Text="КАЧЕСТВО" Foreground="#777771" FontSize="10" FontWeight="Bold"/><ComboBox x:Name="QualityBox" Margin="0,6,0,18"><ComboBoxItem Content="Высокое"/><ComboBoxItem Content="Сбалансированное"/><ComboBoxItem Content="Маленький размер"/></ComboBox><Border Background="#F5F5F3" CornerRadius="10" Padding="12"><StackPanel><TextBlock Text="Папка результата" FontWeight="SemiBold" FontSize="12"/><TextBlock Text="ready convertation" Foreground="#777771" FontSize="12" Margin="0,3,0,0"/></StackPanel></Border></StackPanel>
   </Border>
  </Grid>
  <Grid Grid.Row="4"><StackPanel VerticalAlignment="Center"><TextBlock x:Name="StatusText" Text="Добавьте файлы для начала" Foreground="#777771" FontSize="12" MaxWidth="650" TextTrimming="CharacterEllipsis"/><ProgressBar x:Name="Progress" Height="10" Width="620" HorizontalAlignment="Left" Margin="0,8,0,0" Minimum="0" Maximum="100" Value="0" Foreground="#111111" Background="#DDDDD8"/></StackPanel><Button x:Name="ConvertButton" Content="Начать" HorizontalAlignment="Right" Padding="30,12" IsEnabled="False"/></Grid>
 </Grid>
</Window>
'@

$window = [Windows.Markup.XamlReader]::Load((New-Object System.Xml.XmlNodeReader $xaml))
foreach ($n in 'AddButton','ClearButton','QueueTitle','FileList','EmptyState','FolderButton','RenameButton','RemoveButton','SettingsPanel','SettingsColumn','ActionBox','FormatBox','QualityBox','StatusText','Progress','ConvertButton') { Set-Variable $n $window.FindName($n) }
$QualityBox.SelectedIndex = 1
$files = New-Object System.Collections.ObjectModel.ObservableCollection[object]
$nodes = New-Object System.Collections.ObjectModel.ObservableCollection[object]
$FileList.ItemsSource = $nodes
$appRoot = if($env:MEDIAFORGE_ROOT){$env:MEDIAFORGE_ROOT.TrimEnd('\')}else{(Get-Location).Path}
$imageExt = '.jpg','.jpeg','.png','.webp','.bmp','.gif','.tif','.tiff','.avif'
$videoExt = '.mp4','.mov','.mkv','.avi','.webm','.wmv','.m4v'
$audioExt = '.mp3','.wav','.flac','.m4a','.aac','.ogg','.opus','.wma'

function Format-Size([long]$b) { if($b-ge 1GB){'{0:N1} ГБ'-f($b/1GB)}elseif($b-ge 1MB){'{0:N1} МБ'-f($b/1MB)}elseif($b-ge 1KB){'{0:N0} КБ'-f($b/1KB)}else{"$b Б"} }
function Get-Category([string]$p) { $e=[IO.Path]::GetExtension($p).ToLower(); if($imageExt-contains $e){'Изображение'}elseif($videoExt-contains $e){'Видео'}elseif($audioExt-contains $e){'Аудио'}else{$null} }
function Get-ChoiceText($box) { if($null-eq $box.SelectedItem){return ''}; if($box.SelectedItem -is [Windows.Controls.ComboBoxItem]){return [string]$box.SelectedItem.Content}; return [string]$box.SelectedItem }
function Update-UI {
 $QueueTitle.Text="Файлы · $($files.Count)"; $EmptyState.Visibility=if($files.Count){'Collapsed'}else{'Visible'}; $ConvertButton.IsEnabled=($files.Count-gt 0);$SettingsPanel.Visibility=if($files.Count){'Visible'}else{'Collapsed'};$SettingsColumn.Width=if($files.Count){New-Object Windows.GridLength 300}else{New-Object Windows.GridLength 0}
 $ActionBox.Items.Clear(); [void]$ActionBox.Items.Add('Конвертировать'); [void]$ActionBox.Items.Add('Сжать')
 if($files.Count -gt 0 -and -not ($files|Where-Object Category -eq 'Изображение')){[void]$ActionBox.Items.Add('Извлечь звук')}
 $ActionBox.SelectedIndex=0
}
function Update-Formats {
 $FormatBox.Items.Clear(); if(-not $files.Count){return}; $cat=$files[0].Category; $act=Get-ChoiceText $ActionBox
 if($act-eq 'Извлечь звук'){$vals='MP3','WAV','FLAC','M4A'}
 elseif($cat-eq 'Изображение'){$vals=if($act-eq 'Сжать'){'WebP','JPG','PNG'}else{'JPG','PNG','WebP','AVIF','BMP'}}
 elseif($cat-eq 'Видео'){$vals=if($act-eq 'Сжать'){'MP4 (H.264)','MP4 (H.265)','WebM'}else{'MP4','MOV','MKV','WebM'}}
 else{$vals=if($act-eq 'Сжать'){'MP3','M4A','OGG'}else{'MP3','WAV','FLAC','M4A','OGG'}}
 foreach($v in $vals){[void]$FormatBox.Items.Add($v)}; $FormatBox.SelectedIndex=0
}
function Add-Files([string[]]$paths){$target=$FileList.SelectedItem;$container=$nodes;if($target -and $target.IsFolder){$container=$target.Children};foreach($p in $paths){$cat=Get-Category $p;if($cat -and -not($files|Where-Object Path -eq $p)){$i=Get-Item -LiteralPath $p;$thumb=$null;if($cat-eq 'Изображение'){$thumb=$i.FullName};$item=[pscustomobject]@{Name=$i.Name;Category=$cat;Size=(Format-Size $i.Length);Path=$i.FullName;Thumbnail=$thumb;IsImage=($cat-eq 'Изображение');IsFolder=$false;Children=$null};$files.Add($item);$container.Add($item)}};Update-UI;Update-Formats}

function Remove-VisualNode($collection,$target){if($collection.Contains($target)){$collection.Remove($target);return $true};foreach($node in @($collection)){if($node.IsFolder -and (Remove-VisualNode $node.Children $target)){return $true}};return $false}
function Remove-LogicalFiles($item){if($item.IsFolder){foreach($child in @($item.Children)){Remove-LogicalFiles $child}}else{[void]$files.Remove($item)}}

function Show-AddDialog {
 [xml]$dx=@'
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml" Title="Добавить файлы" Width="520" Height="350" WindowStartupLocation="CenterOwner" ResizeMode="NoResize" Background="#F5F5F3" FontFamily="Segoe UI Variable Text,Segoe UI" AllowDrop="True"><Grid Margin="24"><Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="18"/><RowDefinition Height="*"/></Grid.RowDefinitions><Grid><StackPanel><TextBlock Text="Добавить файлы" FontSize="21" FontWeight="SemiBold"/><TextBlock Text="Изображения, видео или аудио" Foreground="#777771" Margin="0,4,0,0"/></StackPanel><Button x:Name="Close" Content="×" Width="36" Height="36" HorizontalAlignment="Right" Background="White" BorderBrush="#DDDDD8" BorderThickness="1" FontSize="20"/></Grid><Border x:Name="Drop" Grid.Row="2" Background="White" BorderBrush="#CFCFCA" BorderThickness="1" CornerRadius="14" AllowDrop="True"><StackPanel VerticalAlignment="Center" HorizontalAlignment="Center"><TextBlock Text="＋" FontSize="30" HorizontalAlignment="Center"/><TextBlock Text="Перетащите файлы сюда" FontSize="16" FontWeight="SemiBold" Margin="0,9,0,0"/><TextBlock Text="или выберите на компьютере" Foreground="#888882" Margin="0,4,0,14"/><Button x:Name="Browse" Content="Выбрать файлы" Background="#111111" Foreground="White" BorderThickness="0" Padding="18,10"/></StackPanel></Border></Grid></Window>
'@
 $d=[Windows.Markup.XamlReader]::Load((New-Object System.Xml.XmlNodeReader $dx));$d.Owner=$window;$close=$d.FindName('Close');$browse=$d.FindName('Browse');$drop=$d.FindName('Drop')
 $close.Add_Click({$d.Close()});$browse.Add_Click({$o=New-Object Microsoft.Win32.OpenFileDialog;$o.Multiselect=$true;$o.Filter='Медиа|*.jpg;*.jpeg;*.png;*.webp;*.bmp;*.gif;*.tif;*.tiff;*.avif;*.mp4;*.mov;*.mkv;*.avi;*.webm;*.wmv;*.m4v;*.mp3;*.wav;*.flac;*.m4a;*.aac;*.ogg;*.opus;*.wma|Все файлы|*.*';if($o.ShowDialog()){$d.Tag=$o.FileNames;$d.DialogResult=$true}})
 $d.Add_DragOver({param($s,$e)$e.Effects='Copy';$e.Handled=$true});$d.Add_Drop({param($s,$e)if($e.Data.GetDataPresent([Windows.DataFormats]::FileDrop)){$d.Tag=$e.Data.GetData([Windows.DataFormats]::FileDrop);$d.DialogResult=$true}})
 if($d.ShowDialog()){Add-Files $d.Tag}
}
function Show-RenameDialog($item){
 [xml]$rx=@'
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml" Title="Переименовать" Width="430" Height="230" WindowStartupLocation="CenterOwner" ResizeMode="NoResize" Background="#F5F5F3" FontFamily="Segoe UI Variable Text,Segoe UI"><Grid Margin="24"><Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="18"/><RowDefinition Height="44"/><RowDefinition Height="20"/><RowDefinition Height="Auto"/></Grid.RowDefinitions><TextBlock Text="Новое имя файла" FontSize="20" FontWeight="SemiBold"/><TextBox x:Name="NameBox" Grid.Row="2" Background="White" BorderBrush="#D5D5D0" BorderThickness="1" Padding="12,10" FontSize="14"/><StackPanel Grid.Row="4" Orientation="Horizontal" HorizontalAlignment="Right"><Button x:Name="Cancel" Content="Отмена" Background="Transparent" Foreground="#555550" BorderThickness="0" Padding="15,9"/><Button x:Name="Save" Content="Сохранить" Background="#111111" Foreground="White" BorderThickness="0" Padding="18,9" Margin="7,0,0,0"/></StackPanel></Grid></Window>
'@
 $d=[Windows.Markup.XamlReader]::Load((New-Object System.Xml.XmlNodeReader $rx));$d.Owner=$window;$box=$d.FindName('NameBox');$box.Text=[IO.Path]::GetFileNameWithoutExtension($item.Name);$d.FindName('Cancel').Add_Click({$d.DialogResult=$false});$d.FindName('Save').Add_Click({if($box.Text.Trim()){$d.Tag=$box.Text.Trim();$d.DialogResult=$true}});$d.Add_ContentRendered({$box.Focus();$box.SelectAll()});if($d.ShowDialog()){$item.Name=$d.Tag+[IO.Path]::GetExtension($item.Name);$FileList.Items.Refresh();return $true};return $false
}

function Safe-Base([string]$n){$r=[IO.Path]::GetFileNameWithoutExtension($n);foreach($c in [IO.Path]::GetInvalidFileNameChars()){$r=$r.Replace([string]$c,'_')};if($r.Trim()){$r.Trim()}else{'media'}}
function Unique-Path($folder,$base,$ext){$p=Join-Path $folder "$base.$ext";$i=2;while(Test-Path -LiteralPath $p){$p=Join-Path $folder "$base ($i).$ext";$i++};$p}
function Get-Spec($action,$format,$quality,$category){$crf=@(18,23,30)[$quality];$aq=@('320k','192k','128k')[$quality];$iq=@(2,5,9)[$quality]
 if($action-eq 'Извлечь звук' -or $category-eq 'Аудио'){switch($format){'WAV'{return @{e='wav';a='-vn -c:a pcm_s16le'}}'FLAC'{return @{e='flac';a='-vn -c:a flac'}}'M4A'{return @{e='m4a';a="-vn -c:a aac -b:a $aq"}}'OGG'{return @{e='ogg';a="-vn -c:a libopus -b:a $aq"}}default{return @{e='mp3';a="-vn -c:a libmp3lame -b:a $aq"}}}}
 if($category-eq 'Изображение'){switch($format){'PNG'{return @{e='png';a='-frames:v 1 -compression_level 7'}}'WebP'{$q=@(95,80,62)[$quality];return @{e='webp';a="-frames:v 1 -c:v libwebp -quality $q"}}'AVIF'{return @{e='avif';a="-frames:v 1 -c:v libaom-av1 -crf $crf -still-picture 1"}}'BMP'{return @{e='bmp';a='-frames:v 1'}}default{return @{e='jpg';a="-frames:v 1 -q:v $iq"}}}}
 switch($format){'MP4 (H.265)'{return @{e='mp4';a="-c:v libx265 -crf $crf -preset medium -c:a aac -b:a $aq -movflags +faststart"}}'MOV'{return @{e='mov';a="-c:v libx264 -crf $crf -c:a aac"}}'MKV'{return @{e='mkv';a="-c:v libx264 -crf $crf -c:a aac"}}'WebM'{return @{e='webm';a="-c:v libvpx-vp9 -crf $crf -b:v 0 -c:a libopus"}}default{return @{e='mp4';a="-c:v libx264 -crf $crf -preset medium -c:a aac -b:a $aq -movflags +faststart"}}}
}
function Start-FFmpegProcess($inputPath,$outputPath,$ffmpegArgs){$s=New-Object Diagnostics.ProcessStartInfo;$s.FileName='ffmpeg.exe';$s.Arguments="-hide_banner -loglevel error -y -i `"$inputPath`" $ffmpegArgs `"$outputPath`"";$s.UseShellExecute=$false;$s.CreateNoWindow=$true;$s.RedirectStandardError=$true;$p=New-Object Diagnostics.Process;$p.StartInfo=$s;[void]$p.Start();$p}

function Show-ConversionDialog($items,$action,$format,$extension){
 [xml]$cx=@'
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation" xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml" Title="Подготовка конвертации" Width="820" Height="570" MinHeight="470" WindowStartupLocation="CenterOwner" Background="#F5F5F3" FontFamily="Segoe UI Variable Text,Segoe UI"><Grid Margin="26"><Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="18"/><RowDefinition Height="Auto"/><RowDefinition Height="18"/><RowDefinition Height="*"/><RowDefinition Height="18"/><RowDefinition Height="Auto"/></Grid.RowDefinitions><StackPanel><TextBlock Text="Подготовка файлов" FontSize="22" FontWeight="SemiBold"/><TextBlock Text="Дважды нажмите на имя справа, чтобы изменить его" Foreground="#777771" Margin="0,4,0,0"/></StackPanel><Border Grid.Row="2" Background="White" CornerRadius="11" Padding="14"><StackPanel Orientation="Horizontal"><StackPanel Width="220"><TextBlock Text="ДЕЙСТВИЕ" FontSize="10" FontWeight="Bold" Foreground="#777771"/><TextBlock x:Name="ActionText" Margin="0,4,0,0" FontWeight="SemiBold"/></StackPanel><StackPanel><TextBlock Text="ФОРМАТ" FontSize="10" FontWeight="Bold" Foreground="#777771"/><TextBlock x:Name="FormatText" Margin="0,4,0,0" FontWeight="SemiBold"/></StackPanel></StackPanel></Border><DataGrid x:Name="PreviewGrid" Grid.Row="4" AutoGenerateColumns="False" CanUserAddRows="False" HeadersVisibility="Column" GridLinesVisibility="None" Background="White" BorderThickness="0" RowHeight="62" AlternatingRowBackground="#FAFAF8" SelectionUnit="FullRow"><DataGrid.Resources><Style TargetType="DataGridColumnHeader"><Setter Property="Background" Value="#F5F5F3"/><Setter Property="Foreground" Value="#777771"/><Setter Property="BorderThickness" Value="0"/><Setter Property="Padding" Value="10"/></Style><Style TargetType="DataGridCell"><Setter Property="BorderThickness" Value="0"/><Setter Property="Padding" Value="8"/><Setter Property="VerticalContentAlignment" Value="Center"/><Setter Property="Background" Value="Transparent"/></Style></DataGrid.Resources><DataGrid.Columns><DataGridTemplateColumn Header="ИСХОДНЫЙ ФАЙЛ" Width="*"><DataGridTemplateColumn.CellTemplate><DataTemplate><StackPanel Orientation="Horizontal"><Border Width="40" Height="40" CornerRadius="7" Background="#E5E5E0" ClipToBounds="True"><Image Source="{Binding Thumbnail}" Stretch="UniformToFill"/></Border><TextBlock Text="{Binding ShortName}" Margin="10,0,0,0" VerticalAlignment="Center" FontWeight="SemiBold"/></StackPanel></DataTemplate></DataGridTemplateColumn.CellTemplate></DataGridTemplateColumn><DataGridTemplateColumn Header="" Width="45"><DataGridTemplateColumn.CellTemplate><DataTemplate><Path Data="M1,5 L13,5 M9,1 L13,5 L9,9" Stroke="#777771" StrokeThickness="1.4" Width="15" Height="11" Stretch="Uniform"/></DataTemplate></DataGridTemplateColumn.CellTemplate></DataGridTemplateColumn><DataGridTemplateColumn Header="ГОТОВЫЙ ФАЙЛ" Width="*"><DataGridTemplateColumn.CellTemplate><DataTemplate><StackPanel Orientation="Horizontal"><Border Width="40" Height="40" CornerRadius="7" Background="#E5E5E0" ClipToBounds="True"><Image Source="{Binding Thumbnail}" Stretch="UniformToFill"/></Border><TextBlock Text="{Binding OutputDisplay}" Margin="10,0,0,0" VerticalAlignment="Center" FontWeight="SemiBold"/></StackPanel></DataTemplate></DataGridTemplateColumn.CellTemplate><DataGridTemplateColumn.CellEditingTemplate><DataTemplate><TextBox Text="{Binding OutputBase,UpdateSourceTrigger=PropertyChanged}" BorderBrush="#AAAAA4" Padding="8"/></DataTemplate></DataGridTemplateColumn.CellEditingTemplate></DataGridTemplateColumn></DataGrid.Columns></DataGrid><StackPanel Grid.Row="6" Orientation="Horizontal" HorizontalAlignment="Right"><Button x:Name="Cancel" Content="Отмена" Background="Transparent" Foreground="#555550" BorderThickness="0" Padding="16,10"/><Button x:Name="Go" Content="Конвертировать" Background="#111111" Foreground="White" BorderThickness="0" Padding="22,11" Margin="8,0,0,0"/></StackPanel></Grid></Window>
'@
 $d=[Windows.Markup.XamlReader]::Load((New-Object System.Xml.XmlNodeReader $cx));$d.Owner=$window;$d.FindName('ActionText').Text=$action;$d.FindName('FormatText').Text=$format;$grid=$d.FindName('PreviewGrid');$grid.ItemsSource=$items;$grid.Add_CellEditEnding({param($s,$e)$window.Dispatcher.BeginInvoke([Action]{$grid.Items.Refresh()},[Windows.Threading.DispatcherPriority]::Background)|Out-Null});$d.FindName('Cancel').Add_Click({$d.DialogResult=$false});$d.FindName('Go').Add_Click({$grid.CommitEdit();$d.DialogResult=$true});return $d.ShowDialog()
}

$AddButton.Add_Click({Show-AddDialog});$window.Add_DragOver({param($s,$e)$e.Effects='Copy';$e.Handled=$true});$window.Add_Drop({param($s,$e)if($e.Data.GetDataPresent([Windows.DataFormats]::FileDrop)){Add-Files $e.Data.GetData([Windows.DataFormats]::FileDrop)}})
$ClearButton.Add_Click({$files.Clear();$nodes.Clear();Update-UI;$FormatBox.Items.Clear();$StatusText.Text='Добавьте файлы для начала';$Progress.Value=0})
$FolderButton.Add_Click({$temp=[pscustomobject]@{Name='Новая папка'};if(Show-RenameDialog $temp){$children=New-Object System.Collections.ObjectModel.ObservableCollection[object];$folder=[pscustomobject]@{Name=$temp.Name;Category='Папка';Size='';Path=$null;Thumbnail=$null;IsImage=$false;IsFolder=$true;Children=$children};$selected=$FileList.SelectedItem;if($selected -and -not $selected.IsFolder){[void](Remove-VisualNode $nodes $selected);$children.Add($selected)};$nodes.Add($folder)}})
$RemoveButton.Add_Click({if($FileList.SelectedItem){$selected=$FileList.SelectedItem;Remove-LogicalFiles $selected;[void](Remove-VisualNode $nodes $selected);Update-UI;Update-Formats}})
$RenameButton.Add_Click({if($FileList.SelectedItem){Show-RenameDialog $FileList.SelectedItem}})
$ActionBox.Add_SelectionChanged({Update-Formats})
$ConvertButton.Add_Click({
 if(-not(Get-Command ffmpeg.exe -ErrorAction SilentlyContinue)){[Windows.MessageBox]::Show('FFmpeg не найден.','Media Forge')|Out-Null;return}
 $cats=@($files|Select-Object -ExpandProperty Category -Unique);if($cats.Count-gt 1){[Windows.MessageBox]::Show('Для массовой обработки добавьте файлы одного типа: только изображения, только видео или только аудио.','Media Forge')|Out-Null;return}
 $action=Get-ChoiceText $ActionBox;$format=Get-ChoiceText $FormatBox;$folder=Join-Path $appRoot 'ready convertation';[void](New-Item -ItemType Directory -Path $folder -Force);$spec=Get-Spec $action $format $QualityBox.SelectedIndex $files[0].Category;$preview=New-Object System.Collections.ObjectModel.ObservableCollection[object];foreach($f in $files){$base=Safe-Base $f.Name;$short=if($base.Length-gt 7){$base.Substring(0,7)+'….'+$([IO.Path]::GetExtension($f.Name).TrimStart('.'))}else{$f.Name};$row=[pscustomobject]@{Source=$f;ShortName=$short;Thumbnail=$f.Thumbnail;OutputBase=$base;Extension=$spec.e};$row|Add-Member ScriptProperty OutputDisplay {$this.OutputBase+'.'+$this.Extension};$preview.Add($row)}
 if(-not(Show-ConversionDialog $preview $action $format $spec.e)){return}
 $jobs=@();foreach($row in $preview){$sp=Get-Spec $action $format $QualityBox.SelectedIndex $row.Source.Category;$jobs+=[pscustomobject]@{i=$row.Source.Path;o=(Unique-Path $folder (Safe-Base $row.OutputBase) $sp.e);a=$sp.a;n=$row.Source.Name}}
 $ConvertButton.IsEnabled=$false;$ConvertButton.Content='Конвертация…';$Progress.Value=0;$script:state=[pscustomobject]@{j=$jobs;x=0;p=$null;started=$null;bad=(New-Object Collections.Generic.List[string]);folder=$folder;timer=$null};$timer=New-Object Windows.Threading.DispatcherTimer;$script:state.timer=$timer;$timer.Interval=[TimeSpan]::FromMilliseconds(120)
 $timer.Add_Tick({$st=$script:state;if($null-eq $st.p){$cur=$st.j[$st.x];$StatusText.Text="Обрабатывается $($st.x+1) из $($st.j.Count): $($cur.n)";try{$st.p=Start-FFmpegProcess $cur.i $cur.o $cur.a;$st.started=Get-Date}catch{$st.bad.Add("$($cur.n): $($_.Exception.Message)");$st.x++};return};if(-not $st.p.HasExited){$within=[Math]::Min(0.90,((Get-Date)-$st.started).TotalSeconds/8);$Progress.Value=[int](100*($st.x+$within)/$st.j.Count);return};$err=$st.p.StandardError.ReadToEnd();if($st.p.ExitCode-ne 0){$st.bad.Add("$($st.j[$st.x].n): $err")};$st.p.Dispose();$st.p=$null;$st.x++;$Progress.Value=[int]($st.x*100/$st.j.Count);if($st.x-lt $st.j.Count){return};$st.timer.Stop();$ConvertButton.IsEnabled=$true;$ConvertButton.Content='Начать';if($st.bad.Count){$StatusText.Text="Завершено с ошибками · $($st.bad.Count)";$log=Join-Path $st.folder 'conversion-errors.log';$st.bad|Out-File -LiteralPath $log -Encoding utf8;[Windows.MessageBox]::Show("Некоторые файлы не обработаны. Подробности записаны в conversion-errors.log.`n`n$((($st.bad|Select-Object -First 2)-join "`n`n"))",'Media Forge')|Out-Null}else{$StatusText.Text="Готово · $($st.folder)";Start-Process explorer.exe -ArgumentList "`"$($st.folder)`""}});$timer.Start()
})
Update-UI
[void]$window.ShowDialog()
